import {validHalfEquation} from './half-equations.js?v=20261023-physicscomplete01';
import {migrateTopicState,lessonEligible} from './registry.js?v=20261023-physicscomplete01';
export const STORAGE_KEY='crash-course-v2';
export const subjects=[{id:'science',name:'Science',course:'AQA GCSE Science',status:'available',description:'Biology, Chemistry and Physics'},{id:'maths',name:'Maths',course:'Edexcel GCSE Mathematics',status:'available',description:'50 lessons: Number, Algebra, Ratio and Geometry'},{id:'english-language',name:'English Language',course:'GCSE English Language',status:'planned',description:'Lessons coming later'},{id:'english-literature',name:'English Literature',course:'GCSE English Literature',status:'planned',description:'Lessons coming later'},{id:'history',name:'History',course:'GCSE History',status:'planned',description:'Lessons coming later'},{id:'geography',name:'Geography',course:'GCSE Geography',status:'planned',description:'Lessons coming later'}];
export function freshState(){return {version:2,subject:'science',route:'combined',tier:'Foundation',lessonId:'particles',lessons:{},concepts:{},assessment:null};}
export function restore(raw,legacy,lessons){let s=freshState();try{const v=JSON.parse(raw);if(v?.version===2){s={...s,...v,lessons:v.lessons&&typeof v.lessons==='object'&&!Array.isArray(v.lessons)?v.lessons:{},concepts:v.concepts&&typeof v.concepts==='object'&&!Array.isArray(v.concepts)?v.concepts:{}};}else{const old=JSON.parse(legacy);if(old){s.route=old.route;s.tier=old.tier;s.legacy={stage:old.stage,done:old.done};}}}catch{}s.subject=subjects.some(x=>x.id===s.subject)?s.subject:'science';s.route=s.route==='separate'?'separate':'combined';s.tier=s.tier==='Higher'?'Higher':'Foundation';const chosen=lessons.find(l=>l.id===s.lessonId);s.lessonId=chosen&&lessonEligible(chosen,s.route,s.tier)?chosen.id:(lessons.find(l=>l.topicId===chosen?.topicId&&lessonEligible(l,s.route,s.tier))?.id||'particles');return migrateTopicState(s,lessons);}
export function session(s,id){const defaults={stage:0,card:0,learnSeen:[],widget:{},widgetDone:false,practiceIndex:0,practice:{},checkIndex:0,checks:{},run:1,complete:false,mastery:0,reviewAt:null};const p=s.lessons[id];if(!p||typeof p!=='object'||Array.isArray(p))s.lessons[id]=defaults;else for(const [k,v] of Object.entries(defaults))if(p[k]===undefined)p[k]=v;return s.lessons[id];}
export function eligible(lessons,route,tier='Higher'){return lessons.filter(l=>lessonEligible(l,route,tier));}
export function isCorrect(q,value){if(q.type==='equation')return validHalfEquation(value,q.answer);if(q.type==='number')return value!==''&&value!==null&&value!==undefined&&Number.isFinite(Number(value))&&Math.abs(Number(value)-q.answer)<=(q.tolerance||0);return value===q.answer;}
export function grade(rows,qs){const attempted=qs.filter(q=>rows[q.id]!==undefined);const correct=attempted.filter(q=>isCorrect(q,rows[q.id])).length;return {attempted:attempted.length,correct,total:qs.length,percent:qs.length?Math.round(correct/qs.length*100):0,finished:attempted.length===qs.length};}
export function recordConcept(s,key,correct,now=Date.now(),review=false){const c=s.concepts[key]||{correct:0,wrong:0,needsReview:false,interval:0,due:now};if(correct){c.correct++;if(!review&&!c.needsReview&&c.interval===0){c.interval=1;c.due=now+86400000;}if(review){c.needsReview=false;c.interval=c.interval===0?1:Math.min(c.interval*3,21);c.due=now+c.interval*86400000;}}else{c.wrong++;c.needsReview=true;c.interval=0;c.due=now;}c.lastAttempt=now;s.concepts[key]=c;return c;}
export function updateCompletion(p,lesson,practice,checks,now=Date.now()){const g=grade(p.checks,checks);if(lesson.widgetRequirements){let req=lesson.widgetRequirements; p.widgetDone=req[lesson.learnerTier||'Higher'].every(id=>(p.widget[req.completionKey]||[]).includes(id));}p.mastery=g.percent;const practiced=practice.every(q=>p.practice[q.id]?.correct===true);const ready=lesson.learn.every((_,i)=>p.learnSeen.includes(i))&&p.widgetDone&&practiced&&g.finished&&g.percent>=80;if(ready&&!p.complete)p.reviewAt=now+86400000;p.complete=ready;return ready;}
export function dueConcepts(s,now=Date.now()){return Object.entries(s.concepts).filter(([,c])=>c.needsReview||c.due<=now).map(([id])=>id);}
